import numpy as np

def problem(x: np.ndarray) -> float:
    n = x.shape[0]
    f = 0.1 * np.sum(x**2) + 0.05 * np.sum(x**3) + 0.02 * np.sum(np.abs(x))
    for i in range(n):
        for j in range(i + 1, n):
            f += 0.01 * x[i] * x[j]
    return f

import numpy as np

def problem(x: np.ndarray) -> float:
    n = x.shape[0]
    if n != 5:
        raise ValueError("Dimension must be 5.")

    f = np.sum((np.arange(n) + 1) * x**2)

    for i in range(n):
        for j in range(i + 1, n):
            f += 0.5 * (i + j + 1) * x[i] * x[j]

    f += 0.1 * np.sum(x**3)

    f *= 0.1

    return f

