import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function for global optimization.
    """
    n = x.shape[0]
    if n != 5:
        raise ValueError("Dimension must be 5.")

    f = 0.0
    for i in range(n):
        f += (i + 1) * x[i]**2

    for i in range(n):
        for j in range(i + 1, n):
            f += 0.5 * (i + j + 1) * x[i] * x[j]

    f += 0.1 * np.sum(x**3)

    sigmoid_product = 1.0
    for i in range(n):
        sigmoid_product *= 1.0 / (1 + np.exp(-x[i] * (i + 1)))

    f *= 0.1 * sigmoid_product

    return f

