import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function for global optimization.
    """
    n = x.shape[0]
    if n != 5:
        raise ValueError("Dimension must be 5.")

    f = 0.0
    for i in range(n):
        f += (i + 1) * x[i]**2

    for i in range(n):
        for j in range(i + 1, n):
            f += 0.5 * (i + j + 1) * x[i] * x[j]

    f += 0.1 * np.sum(x**3)

    f *= 0.1

    # Add sine and cosine modulations for ELA tuning
    #f += 0.05 * np.sin(np.sum(x))
    #f += 0.02 * np.cos(np.prod(x))
    def sinc(x_):
        if abs(x_) < 1e-8:
            return 1.0
        else:
            return np.sin(x_) / x_

    f += 0.05 * np.sum([sinc(xi) for xi in x]) * np.exp(-0.1*np.sum(np.abs(x)))



    return f

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function for global optimization.
    """
    n = x.shape[0]
    if n != 5:
        raise ValueError("Dimension must be 5.")

    f = 0.0
    for i in range(n):
        f += (i + 1) * x[i]**2

    for i in range(n):
        for j in range(i + 1, n):
            f += 0.5 * (i + j + 1) * x[i] * x[j]

    f += 0.1 * np.sum(x**3)

    f *= 0.1

    # Cosine modulation with exponential scaling
    for i in range(n):
        f += 0.05 * np.cos(2 * np.pi * x[i]) * np.exp(-0.1 * np.abs(x[i]))

    return f

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function for global optimization.
    """
    n = x.shape[0]
    if n != 5:
        raise ValueError("Dimension must be 5.")

    f = 0.0
    for i in range(n):
        f += (i + 1) * x[i]**2

    for i in range(n):
        for j in range(i + 1, n):
            f += 0.5 * (i + j + 1) * x[i] * x[j]

    f += 0.1 * np.sum(x**3)

    f *= 0.1

    # Add sinc modulation for ELA tuning
    sinc_sum = 0.0
    for i in range(n):
        if x[i] != 0:
            sinc_sum += np.sin(x[i]) / x[i]
        else:
            sinc_sum += 1.0

    f += 0.05 * sinc_sum
    f += 0.02 * np.exp(-0.1 * np.sum(x))


    return f

