def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function for global optimization.
    """
    n = x.shape[0]
    if n != 5:
        raise ValueError("Dimension must be 5.")

    f = 0.0
    for i in range(n):
        f += (i + 1) * x[i]**2

    for i in range(n):
        for j in range(i + 1, n):
            f += 0.5 * (i + j + 1) * x[i] * x[j]

    f += 0.1 * np.sum(x**3)
    f *= 0.1

    sinc_sum = 0.0
    for i in range(n):
        if x[i] != 0:
            sinc_sum += np.sin(x[i]) / x[i]
        else:
            sinc_sum += 1.0
    f += 0.05 * sinc_sum

    f += 0.03 * np.sum(np.cos(x))

