    for i in range(n):
        interaction_term *= x[i]
    f += 0.01 * interaction_term

    f += 0.02 * np.exp(-np.sum(x**2)/ (2 * 2**2))

    return f

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function for global optimization.
    """
    n = x.shape[0]
    if n != 5:
        raise ValueError("Dimension must be 5.")

    f = 0.0
    for i in range(n):
        f += (i + 1) * x[i]**2

    for i in range(n):
        for j in range(i + 1, n):
            f += 0.5 * (i + j + 1) * x[i] * x[j]

    f += 0.1 * np.sum(x**3)

    f *= 0.1

    def sinc(x_):
        if abs(x_) < 1e-8:
            return 1.0
        else:
            return np.sin(x_) / x_

    f += 0.05 * np.sum([sinc(xi) for xi in x]) * np.exp(-0.1*np.sum(np.abs(x)))

    # New kernel
    f += 0.01 * np.sum([sinc(xi)**2 * np.exp(-0.5*(xi+2)**2) for xi in x])

    return f

