def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function for global optimization.
    """
    n = x.shape[0]
    if n != 5:
        raise ValueError("Dimension must be 5.")

    f = 0.0
    for i in range(n):
        f += (i + 1) * x[i]**2

    for i in range(n):
        for j in range(i + 1, n):
            f += 0.5 * (i + j + 1) * x[i] * x[j]

    f *= 0.1

    # Inverse squared distance term modulated by sine
    for i in range(n):
        f += 0.05 * np.sin(np.sum(x)) / (1.0 + x[i]**2)

    return f

