import numpy as np

def problem(x: np.ndarray) -> float:
    n = x.shape[0]
    if n != 5:
        raise ValueError("Dimension must be 5.")

    f = 0.0
    for i in range(n):
        f += (i + 1) * x[i]**2

    for i in range(n):
        for j in range(i + 1, n):
            f += 0.5 * (i + j + 1) * x[i] * x[j]

    f += 0.1 * np.sum(x**3)
    f *= 0.03

    r = np.sqrt(np.sum(x**2))
    f += 0.02 * np.log(np.sum(np.exp(np.cos(r*x) - r)))

    return f

