import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function for global optimization.
    """
    n = x.shape[0]
    if n != 5:
        raise ValueError("Dimension must be 5.")

    f = 0.0
    for i in range(n):
        f += (i + 1) * x[i]**2

    for i in range(n):
        for j in range(i + 1, n):
            f += 0.5 * (i + j + 1) * x[i] * x[j]

    f += 0.15 * np.sum(x**3) # Increased skewness
    f *= 0.1

    sinc_sum = 0.0
    for i in range(n):
        if x[i] != 0:
            sinc_sum += np.sin(x[i]) / x[i]
        else:
            sinc_sum += 1.0
    f += 0.07 * sinc_sum # Increased sinc influence

    f += 0.03 * np.sum(np.cos(x))

    interaction_term = 1.0
    for i in range(n):
        interaction_term *= x[i]
    f += 0.005 * interaction_term # Reduced interaction influence

    f += 0.02 * np.exp(-np.sum(x**2)/ (2 * 2**2))

    # Add a log-sum-exp term for finer control of the landscape
    f += 0.015 * np.log(np.sum(np.exp(x)))# Increased log sum exp

    #Scaled additional interactions
    for i in range(n):
      for j in range(i + 1 , n):
        f += (0.003 * (i+j+1) * np.sin(x[i]) * np.cos(x[j]))

    return f

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function for global optimization.
    """
    n = x.shape[0]
    if n != 5:
        raise ValueError("Dimension must be 5.")

    # Quadratic function with interaction terms
    f = 0.0
    for i in range(n):
        f += (i + 1) * x[i]**2
    for i in range(n):
        for j in range(i + 1, n):
            f += 0.5 * (i + j + 1) * x[i] * x[j]

    # Dimensionally scaled radius
    r = np.sqrt(np.sum((x / np.arange(1, n + 1))**2))

    # Chebyshev polynomial of the second kind (U)
    def chebyshev_U(x, n):
        if n == 0:
            return 1
        elif n == 1:
            return 2 * x
        else:
            return 2 * x * chebyshev_U(x, n-1) - chebyshev_U(x, n-2)

    # Radial Chebyshev polynomial with exponential decay
    f += 0.5 * chebyshev_U(r,3) * np.exp(-r**2)

    f += 0.05 * np.sum(x**3)

    # Scale the function
    f *= 0.025

    return f
